//! `emit_field` — prints the HLSL field bodies generated by tracing the generic
//! `boyko_shaderdsl::field` body over the `Emit` backend (`feature = "emit"`).
//!
//! Pass 1: this PRINTS to stdout. It does NOT splice into
//! `crates/boyko_rhi_vulkan/shaders/sdf_field.hlsli` and does NOT recompile any
//! `.spv` — that is Pass 2 (which also adds the `precise` qualifier and re-DXC + the
//! RTX gate). The output here is the textual-equivalence artifact: eyeball the
//! generated `smin`/`smax`/`combine` against the frozen `sdf_field.hlsli:110-129`.
//!
//! Run: `cargo run -p boyko_shaderdsl --features emit --bin emit_field`

fn main() {
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_field());
    // The surface-normal leaf (`sdf_normal`) — the central-difference gradient of the
    // whole edit-list field, generated from the SAME single source (`boyko_shaderdsl::
    // normal::sdf_normal_body`). Spliced between the `// === GENERATED NORMAL
    // BEGIN/END ===` sentinels in `sdf_field.hlsli`.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_normal());
    // The brick snorm decode SCALE leaf (`m2_decode` — the GPU-spliceable `n *
    // band_half`), generated from `boyko_shaderdsl::brick::snorm_scale`. The byte →
    // normalize step is the hardware `R8_SNORM` sampler (not shader code). Spliced
    // between the `// === GENERATED decode_snorm8 BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl`.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_decode_snorm8());
    // The M2 cubic-surface leaves (A3) — the PURE-EXPRESSION leaves of the JCGT cubic
    // solver: `m2_cubic_eval` (Horner) and `m2_jcgt_cubic_coeffs` (the trilinear →
    // cubic-coefficient fold). Generated from `boyko_shaderdsl::brick::{cubic_eval,
    // jcgt_cubic_coeffs}`. Spliced between the `// === GENERATED m2_cubic_eval
    // BEGIN/END ===` and `// === GENERATED m2_jcgt_cubic_coeffs BEGIN/END ===`
    // sentinels in `sdf_gbuffer_composite.hlsl`. The root-finders that CALL them
    // (`m2_marmitt_root` / `m2_regula_falsi`) stay hand-written (runtime control flow).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_cubic_eval());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_jcgt_cubic_coeffs());
    // The brick-exit empty-skip MARCHER leaf (Increment 1 — the first CONTROL-FLOW leaf):
    // the `[unroll]` slab loop with the data-dependent `continue` + the final progress-
    // clamp ternary, generated from `boyko_shaderdsl::brick::dist_to_brick_exit_body` over
    // the `Emit` value backend + the `EmitCf` control-flow backend. Spliced between the
    // `// === GENERATED dist_to_brick_exit BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl`. The host `boyko_sdf_math::brick::dist_to_brick_exit`
    // stays HAND-WRITTEN (firewall option B — see the brick module doc).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_dist_to_brick_exit());
    // The brick-cell pointer-grid lookup MARCHER leaf (Increment 3 — the second CONTROL-FLOW
    // leaf, the first with EARLY RETURNS + a `StructuredBuffer<uint>` load + an `out float3`
    // param + `uint` index math), generated from `boyko_shaderdsl::brick::brick_cell_class_body`
    // over the `Emit` value backend + the `EmitCf` control-flow backend. Spliced between the
    // `// === GENERATED brick_cell_class BEGIN/END ===` sentinels in
    // `sdf_gbuffer_composite.hlsl` (the DEFINITION only — the 3 call sites are untouched). The
    // host `host_brick_cell` (boyko_rhi_vulkan::compute) stays HAND-WRITTEN (firewall option B).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_brick_cell_class());
    // The regula-falsi root-refinement MARCHER leaf (Increment 4a — the THIRD CONTROL-FLOW
    // leaf, the first with a genuine RUNTIME `[loop]` (an `OpLoop`): five loop-carried Phi
    // vars {lo,hi,f_lo,f_hi as suppressed-decl params + mid as a local}, an in-loop early
    // return forwarded to the function IIFE, and a `m2_cubic_eval(c, mid)` call site),
    // generated from `boyko_shaderdsl::brick::m2_regula_falsi_body` over the `Emit` value
    // backend + the `EmitCf` control-flow backend. Spliced between the `// === GENERATED
    // m2_regula_falsi BEGIN/END ===` sentinels in `sdf_gbuffer_composite.hlsl` (the
    // DEFINITION only — the 2 call sites in `m2_marmitt_root` are untouched). The host
    // `boyko_sdf_math::brick::regula_falsi` stays HAND-WRITTEN (firewall option B); the eval
    // oracle is a frozen GPU-shape reference (the GPU's `1.0e-30` denom guard differs from
    // the host's `f32::MIN_POSITIVE`).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_m2_regula_falsi());
    // The soft-shadow penumbra MARCHER leaf (Increment 4b — the FOURTH CONTROL-FLOW leaf, the
    // first with a real `break` + a `field_distance` CALL site): the runtime `[loop]` penumbra
    // accumulation (`min(res, SHADOW_K*d/t)`) with the occluder-hit early return, the
    // `t > T_MAX` break (the `brk` producer), and the `clamp01` tail, generated from
    // `boyko_shaderdsl::shadow::sdf_soft_shadow_body` over the `Emit` + `EmitCf` backends.
    // Spliced between the `// === GENERATED sdf_soft_shadow BEGIN/END ===` sentinels INSIDE
    // `sdf_soft_shadow` (the loop+tail SPAN only — the `dot(n,L)` preamble stays hand-written,
    // framing b). The host shadow march stays ANALYTIC (C1) — only the GPU span is generated.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_sdf_soft_shadow());
    // The M2 brick-marcher SURFACE-HIT refine leaf (Increment 4b.2 — the FIFTH CONTROL-FLOW
    // leaf, reusing the proven runtime `[loop]` + `brk` + `field_distance` `call1`, adding a
    // real `OpTypeBool` return (`Cf::ret_b` — `return true`/`return false`, NOT uint 0/1) + an
    // `out float hit_t` write (`Cf::out_float_assign`), folded by the composite `Cf::if_hit_ret_b`
    // — the production `m2_surface_hit` analytic-residual signed refine: the fixed-budget
    // (`M2_REFINE_ITERS`) sphere-trace from the cubic candidate onto the EXACT field, the
    // converged-hit `hit_t = rt; return true;`, the `rt < 0 || rt > T_MAX` break, and the tail
    // `return false;`, generated from `boyko_shaderdsl::surface::m2_surface_hit_refine_body` over
    // the `Emit` + `EmitCf` backends. Spliced between the `// === GENERATED m2_surface_hit_refine
    // BEGIN/END ===` sentinels INSIDE `m2_surface_hit` (the loop+tail SPAN only — the integer
    // cell-addressing preamble + the `m2_brick_span`/`m2_brick_cubic_hit`/`select_level` call
    // sites stay hand-written, framing b). The 2 callers of `m2_surface_hit` are untouched.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_m2_surface_hit_refine());
    // The B1 over-relaxation ACCEPT-REFINE inner-loop leaf (Increment 4c — the SIXTH CONTROL-FLOW
    // leaf, a near-CLONE of `m2_surface_hit_refine` but STRICTLY SIMPLER: NO return facet — the
    // only loop control is the `abs(rd_) < EPS` `brk`; the field seam interns `sdf` (the ANALYTIC
    // field, NOT `field_distance`); the span prints at DEPTH 3 (the site nests main→`for (it)`→
    // `if (d < EPS)`→this refine loop)). The production B1 marcher's settle-onto-surface refine:
    // the fixed-budget (`M2_REFINE_ITERS`) SIGNED sphere-trace that corrects an over-relaxed
    // accept off the surface (`t = t + M2_REFINE_RELAX * sdf(...)`), accepting on `abs(rd_) < EPS`,
    // generated from `boyko_shaderdsl::refine::b1_accept_refine_body` over the `Emit` + `EmitCf`
    // backends. Spliced between the `// === GENERATED b1_accept_refine BEGIN/END ===` sentinels
    // INSIDE the main B1 marcher (the inner refine `[loop]` SPAN only — the `hit = true;
    // exhausted = false;` accept block + the rationale comment + the outer marcher `break;` stay
    // hand-written, framing b). The host B1 marcher stays hand-written and is not generated.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_b1_accept_refine());
    // The B1 EXHAUSTION RE-MARCH inner-loop leaf (Increment 4e — the SEVENTH CONTROL-FLOW leaf, a
    // near-CLONE of `b1_accept_refine` with 4 new facets: the FLOAT mesh guard `t >= t_mesh`
    // (`FieldScalar::ge`), a NAMED `float3 p` temp (`Cf::temp_vec3`), and the in-loop `hit = true;`
    // (`Cf::set_bool_var`) carried by a SUPPRESSED-DECL bool (`Cf::decl_bool_param`/`get_bool_var`)).
    // The production B1 marcher's BUG-B1-HOLE-3 budget-exhaustion recovery: the plain `omega == 1.0`
    // sphere-trace from the ORIGINAL seed (`t = t + sdf(p)`), run when the over-relaxed fast pass
    // exhausted `MAX_IT` mid-field, with the `t >= t_mesh` mesh-guard break, the `d < EPS` accept
    // (`hit = true; break;`), and the `t > T_MAX` miss break; generated from
    // `boyko_shaderdsl::remarch::b1_exhaustion_remarch_body` over the `Emit` + `EmitCf` backends.
    // Spliced between the `// === GENERATED b1_exhaustion_remarch BEGIN/END ===` sentinels INSIDE
    // the main B1 marcher's `if (exhausted) { ... }` block (the inner re-march `[loop]` SPAN only —
    // the `t = t_seed;` re-seed + the `hit = false;` reset + the BUG-B1-HOLE-3 rationale comment +
    // the `if (exhausted)` wrapper stay hand-written, framing b). The span prints at DEPTH 2 (the
    // site nests main→`if (exhausted)`→this re-march loop). The host B1 marcher stays hand-written
    // and is not generated.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_b1_exhaustion_remarch());
    // The B1 marcher's two `bool` PREAMBLE DECLS (Increment 4d — the FIRST rung of the B1-marcher
    // single-source ladder, the first TYPED `bool` decl facet via `Cf::decl_bool_var`): `bool hit
    // = false;` and `bool exhausted = true;`, generated from `boyko_shaderdsl::decl::{b1_decl_hit_
    // body, b1_decl_exhausted_body}` over the `Emit` + `EmitCf` backends. The two decls are
    // NON-CONTIGUOUS in the committed shader (separated by 4 `float` decls — `safe_t`/`sor_prev`/
    // `sor_step_prev` — + the 7-line BUG-B1-HOLE-3 rationale comment), so each is spliced between
    // its OWN sentinel pair (`// === GENERATED b1_decl_hit BEGIN/END ===` at L1316, `// ===
    // GENERATED b1_decl_exhausted BEGIN/END ===` at L1327 inside the main B1 marcher); the `float`
    // decls + ALL comments BETWEEN them stay HAND-WRITTEN (framing b). The reads/sets of the flags
    // are hand-written / out of scope, so no get/set bool facet is generated at this rung.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_b1_decl_hit());
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_b1_decl_exhausted());
    // The B1 over-relaxation SOR-FAIL-RETREAT STEP span (Increment 4f — the DEFENSIBLE TERMINUS of
    // the B1-marcher single-source ladder: the EIGHTH CONTROL-FLOW leaf, the first with a TWO-arm
    // `if (omega > 1.0) { ... } else { ... }` (`Cf::if_else`), a CAPTURED `uint` `it` read (the
    // `uint` analogue of Inc4e's captured `float t_mesh`), a `uint` `>` guard (`Cf::ugt`) joined by
    // a logical `&&` (`Cf::and2`) to the Lipschitz `<` with a bare `0u` (`Cf::uint_lit`), and the
    // mid-body `continue` (`Cf::cont`)). The production B1 marcher's per-iteration Keinert over-
    // relaxed step (`t = t + d * omega`) with the Lipschitz-aware retreat-to-plain (`t = safe_t +
    // sor_prev; omega = 1.0; continue;` when `it > 0u && sor_prev + d < FIELD_LIPSCHITZ_L *
    // sor_step_prev`), the 0%-gated `else { t = t + d; }` plain arm, and the `t > T_MAX` miss break;
    // generated from `boyko_shaderdsl::sor::b1_sor_retreat_body` over the `Emit` + `EmitCf` backends.
    // `d` is the already-sampled field value (a `float` input — NO field call in this span). Spliced
    // between the `// === GENERATED b1_sor_retreat BEGIN/END ===` sentinels INSIDE the main B1
    // marcher's `for (uint it)` loop (the step SPAN only — the loop header, the mesh-guard, the M1/M2
    // brick islands, `float d = sdf(p);`, the `d < EPS` accept block, and ALL BUG-B1-HOLE rationale
    // comments stay hand-written, framing b; the rationale travels in the sor module doc). This is
    // the SECOND generated sentinel inside that one loop (Inc4c's accept-refine at depth 3 + this at
    // depth 2). The span prints at DEPTH 2 (8-space `if (omega > 1.0)`). The host B1 marcher stays
    // hand-written and is not generated.
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_b1_sor_retreat());
    // The M4 clip-map LEVEL-SELECTOR leaf (Increment 5a — the FIRST signed-`int`-returning leaf,
    // landing the signed-int subsystem): the `[unroll]` finest-first containment scan that returns
    // the tightest enclosing LOD index (`return (int)L;` via `Cf::if_ret_i` + `Cf::int_from_uint`)
    // or `-1` (`return -1;` via `Cf::ret_i` + `Cf::int_lit_signed` — a BARE signed literal, NOT a
    // `<x>u`). The new facets: the signed-int return path (`EmitTy::Int` + `Node::IntLit`/
    // `IntFromUint`), the `all(p >= o) && all(p < hi)` bool3 reduction (`Cf::all3_ge`/`all3_lt`),
    // the push-constant `pc.brick_levels` read (`Cf::pc_uint`), and the `M4Level` access-text reads
    // (`Cf::level_field_vec3`/`level_field_scalar` — `m2_levels[L].…`, the struct layout NOT
    // modeled). The `[unroll]` loop reuses `Cf::runtime_for` (attr `[unroll]`, the bound SYMBOL
    // `BRICK_LEVELS`); the in-loop `(int)L` return forwards through it to the function IIFE.
    // Generated from `boyko_shaderdsl::levels::select_level_body` over the `Emit` + `EmitCf`
    // backends. Spliced between the `// === GENERATED select_level BEGIN/END ===` sentinels INSIDE
    // `select_level` (the SCAN SPAN only — the hand-written `int select_level(float3 p) {` signature
    // + the closing `}` stay un-generated, framing b). The span prints at DEPTH 1 (4-space indent).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_select_level());
    // The M2 brick-AABB ray-span clip leaf (Increment 5b — the SECOND `[unroll]` body after
    // `dist_to_brick_exit`, the first with a COMPUTED-bool return): the standard slab-method clip of
    // the ray `p + rd·t` to ONE brick's `[cell_min, cell_min + brick_world]` AABB, returning the
    // `[t_enter, t_exit]` world-`t` span through TWO `out float` params + a COMPUTED `bool` (`return
    // tmax > tmin;` via `Cf::ret_b_expr` — a Mask operand, vs the `bool`-literal `Cf::ret_b`'s
    // `return false;`). The three new facets: the COMPUTED-bool return (`Cf::ret_b_expr`), the TWO
    // `out float` params (`t_enter`/`t_exit`, both `Cf::out_float_assign`), and the FALL-THROUGH swap
    // `if (t1 > t2) { float tmp = t1; t1 = t2; t2 = tmp; }` (a `Cf::if_` whose body returns
    // `Flow::Continue(())` — the same fall-through shape `m2_regula_falsi`'s bracket `if_else`
    // proved). The `[unroll]` axis loop reuses `Cf::runtime_for` (attr `[unroll]`, the LITERAL bound
    // `"3u"`, NOT `unroll_for`'s form — the in-loop parallel-slab early `return false` must FORWARD
    // through the loop to the function IIFE, which `runtime_for` does and `unroll_for` does not).
    // Generated from `boyko_shaderdsl::brick::m2_brick_span_body` over the `Emit` + `EmitCf` backends.
    // Spliced between the `// === GENERATED m2_brick_span BEGIN/END ===` sentinels INSIDE
    // `m2_brick_span` (the BODY only — the hand-written `bool m2_brick_span(...) {` signature + the
    // closing `}` stay un-generated, framing b). The span prints at DEPTH 1 (4-space indent). There
    // is no host `m2_brick_span` mirror; the eval oracle is a verbatim host transcription of the
    // committed body (the GPU-shape single-source discipline `dist_to_brick_exit` uses).
    println!();
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_m2_brick_span());
}
